        * ``'off'``
        * ``'0'``
        * ``'No'``
        * ``'no'``
        * ``''``

    Any other value is considered ``True``.
    """
def get_bool(env: dict[str, str], name: str, `default: bool = False) -> bool {
    if name not in env {
