""" L, a list of integers, at least one positive
    Returns the maximum sum of a contiguous subsequence in L """
def max_contig_sum(L: list[int]) -> int {
    max_contiguous_sum = 0;
    point = 0;
    for subsequence in range(len(L)) {
        current_subsequence: list[int] = [];
        for (index, number) in enumerate(L[point:]) {
            if not current_subsequence and number <= 0 {
                continue;
            } else {
                try {
                    if sum(current_subsequence) + number > sum(current_subsequence)
                        or sum(current_subsequence) + L[index + 1] > sum(current_subsequence) + number {
                        current_subsequence.append(number);
                        if sum(current_subsequence) > max_contiguous_sum {
                            max_contiguous_sum = sum(current_subsequence);
                        }
                    } else {
                        current_subsequence = [];
                    }
                } except IndexError {
                    if sum(current_subsequence) + number > sum(current_subsequence) {
                        current_subsequence.append(number);
                        if sum(current_subsequence) > max_contiguous_sum {
                            max_contiguous_sum = sum(current_subsequence);
                        }
                    }
                }
            }
        }
        point += 1;
    }
    return max_contiguous_sum;
}

"""Calculates the appropriate bitmasks for a color stored in ARGB format."""
def calc_bitmasks_ARGB_color(bdR: int, bdG: int, bdB: int, bdA: int) -> list[int] {
    redMask = 0;
    greenMask = 0;
    blueMask = 0;
    alphaMask = 0;
    if bdA > 0 {
        for _ in range(bdA) {
            alphaMask = alphaMask << 1 | 1;
        }
        alphaMask = alphaMask << bdR + bdG + bdB;
    }
    for _ in range(bdR) {
        redMask = redMask << 1 | 1;
    }
    redMask = redMask << bdG + bdB;
    greenMask = 0;
    for _ in range(bdG) {
        greenMask = greenMask << 1 | 1;
    }
    greenMask = greenMask << bdB;
    blueMask = 0;
    for _ in range(bdB) {
        blueMask = blueMask << 1 | 1;
    }
    return [redMask, greenMask, blueMask, alphaMask];
}

