"""Return File entity in Demisto format for use in entry context."""
def ec_file(main_object: dict[str, str | None | dict[str, str | None]]) -> dict[str, dict[str, str | None]] {
    name = main_object.get('filename') as str | None;
    hashes = main_object.get('hashes', {}) as dict[str, str | None];
    md5 = hashes.get('md5');
    sha1 = hashes.get('sha1');
