"""Command-line -> method call arg processing.

    - positional args:
            a b -> method('a', 'b')
    - intifying args:
            a 123 -> method('a', 123)
    - json loading args:
            a '["pi", 3.14, null]' -> method('a', ['pi', 3.14, None])
    - keyword args:
            a foo=bar -> method('a', foo='bar')
    - using more of the above
            1234 'extras=["r2"]'  -> method(1234, extras=["r2"])
    """
def _method_info_from_argv(
    argv: list[str] | None = None
) -> tuple[str, list[str | int | float | list | None], dict[str, str | int | float | list | None]] {
    import json;
    import sys;
    if argv is None {
        argv = sys.argv;
    }
    method_name = argv[1];
    arg_strs = argv[2:];
    args: list[str | int | float | list | None] = [];
    kwargs: dict[str, str | int | float | list | None] = {};
    for s in arg_strs {
        if s.count('=') == 1 {
            (key, value) = s.split('=', 1);
        } else {
            (key, value) = (None, s);
        }
        try {
            value = json.loads(value);
        } except ValueError {
            ;
        }
        if key {
            kwargs[key] = value;
        } else {
            args.append(value);
        }
    }
    return (method_name, args, kwargs);
}

