"""Format data as a table."""
def _format_data_as_table(data: dict[str, str] | list[dict[str, str]]) -> str {
    if isinstance(data, dict) {
        data = [data];
    }
    common_keys = {
        key
        for (key, val) in data[0].items()
        if isinstance(val, str)
    };
    for row in data[1:] {
        common_keys = common_keys.intersection(set(row.keys()));
    }
    keys = sorted(common_keys);
    column_width = {val: len(data[0][val]) for val in keys};
    row_format = ''.join(
        [('{:' + str(width) + '}\t\t') for (_, width) in column_width.items()]
    );
    title = row_format.format(*column_width.keys());
    separator_column_width = [('-' * width) for (_, width) in column_width.items()];
    separator = row_format.format(*separator_column_width);
    formatted_data = title + '\n' + separator;
    for entry in data {
        row_data = [entry[key] for key in keys];
        formatted_data += '\n' + row_format.format(*row_data);
    }
    return formatted_data;
}

