"""
Returns smallest x > 0 s.t. pow(a, x, mod) == b or None if no such x exists.
Note: works even if a and mod are not coprime.
"""
def discrete_log(a: int, b: int, mod: int) -> int | None {
    n = int(mod ** 0.5) + 1;
    tiny_step: dict[int, int] = {};
    e = 1;
    for j in range(1, n + 1) {
        e = e * a % mod;
        if e == b {
            return j;
        }
        tiny_step[b * e % mod] = j;
    }
    factor = e;
    for i in range(2, n + 2) {
        e = e * factor % mod;
        if e in tiny_step {
            j = tiny_step[e];
            x = n * i - j;
            return x if pow(a, x, mod) == b else None;
        }
    }
}

glob DISTANCE_THRESHOLD = 20;
glob DIM_X = 100;
glob DIM_Y = 100;

"""Validate crop size and center against image bounds and edge distance."""
def validate_input(crop_size: tuple[int, int], crop_center: tuple[int, int]) -> bool {
    distance = DISTANCE_THRESHOLD;
    (x, y) = crop_center;
    (dx, dy) = crop_size;
    (dx, dy) = (dx // 2, dy // 2);
    margins = [x - dx, DIM_X - (x + dx + 1), y - dy, DIM_Y - (y + dy + 1)];
    return not `any(val < distance for val in margins);
}

"""Removes duplicates from a sorted list"""
def RemoveDuplicate(Sortedlist: list[int | str | float] | range | None) -> list[int | str | float] {
    new_list: list[int | str | float] = [];
    if not Sortedlist {
        return new_list;
    }
    prev: int | str | float | None = None;
    for element in Sortedlist {
        if element != prev {
