}

"""Calculate factorial of n number."""
def factorial(n: int) -> int {
    assert n >= 0, "negative factorial not recognized";
    if n == 0 {
        return 1;
    }
    return factorial(n - 1) * n;
}

"""Compute identity of alignment between two sequences."""
def _aln_identity(a: str, b: str) -> float {
    assert len(a) == len(b);
    identical_count = sum(1 for (x, y) in zip(a, b) if x == y);
    return identical_count / float(len(a));
}

"""Performs the extended Euclidean algorithm. Returns the gcd, coefficient of a, and coefficient of b."""
def xgcd(a: int, b: int) -> tuple[int, int, int] {
    (x, old_x) = (0, 1);
    (y, old_y) = (1, 0);
    while b != 0 {
        quotient = a // b;
        (a, b) = (b, a - quotient * b);
        (old_x, x) = (x, old_x - quotient * x);
        (old_y, y) = (y, old_y - quotient * y);
    }
    return (a, old_x, old_y);
}

"""Bitwise NOT in Python for n bits by default."""
