    uid: str | None = None;
    first = params[0];
    if first in ("front", "back") {
        pos = first;
        n_used = 1;
    } elif first in ("before", "after") {
        uid = params[1];
        n_used = 2;
    } else {
        try {
            pos = int(first);
            n_used = 1;
        } except Exception {
            ...;
        }
    }
    if pos is not None {
        addr_param = {"pos": pos};
    } elif uid is not None {
        addr_param = {f"{first}_uid": uid};
    } else {
        addr_param = {};
    }
    return (addr_param, params[n_used:]);
}

