"""turn the word_counts into a list of triplets w, p(w | spam) and p(w| ~spam)"""
def word_probabilities(
    counts: dict[str, tuple[int, int]],
    total_spams: int,
    total_non_spams: int,
    k: float = 0.5
) -> list[tuple[str, float, float]] {
    return [
        (
            w,
            (spam + k) / (total_spams + 2 * k),
            (non_spam + k) / (total_non_spams + 2 * k)
        )
        for (w, (spam, non_spam)) in counts.items()
    ];
}

"""removes useless points from a path and leaves only turn-points"""
def compress_path(path: list[tuple[int, int]]) -> list[tuple[int, int]] {
    new_path = path;
    i = 0;
    while i < len(new_path) - 2 {
        (x1, y1) = new_path[i];
        (x2, y2) = new_path[i + 1];
        (x3, y3) = new_path[i + 2];
        if (x1 == x2 and x2 == x3) or (y1 == y2 and y2 == y3) {
            new_path.pop(i + 1);
        } else {
            i = i + 1;
        }
    }
    return new_path;
}

