"""Perform recursive fast exponentiation by squaring."""
def fpow0(x: int | float, n: int) -> int | float {
    if n < 0 {
        return fpow0(1 / x, -n);
    }
    if n == 0 {
        return 1;
    }
    if x == 0 {
        return 0;
    }
    assert n == int(n), "n must be an integer";
    return fpow0(x * x, n // 2) if n % 2 == 0 else x * fpow0(x * x, n // 2);
}

""" dimensionless geometry coefficient lambda2
    The corresponding definition (of different separability factor) is provided in Table 1 in [2].
    Note that the definition in [2] is slightly different due to the use of hydraulic radius of channel.
    This means that the lam2 in this code is 4, 3/2, and 3/4 respectively for CM, FMM, and FMS.
    However, the lambda1 in reference [2] is 2, 3/2, and 3/4 respectively for CM, FMM, and FMS (divided by RH/R from lam2 here)
    """
def get_lam2(membrane_geometry: str) -> float {
    match membrane_geometry {
        case 'FMM':
            return 3 / 2.0;
        case 'FMS':
            return 3 / 4.0;
        case _:
            return 4.0;
    }
}

"""Split the coordinate arrays into nparts. Add extra_args to each part."""
def _split_arrays(arrays: list[list[int]], extra_args: list[str], nparts: int) -> list[list[list[int] | str]] {
    size = len(arrays[0]);
    n = size // nparts;
    strides = [(i * n, (i + 1) * n) for i in range(nparts - 1)];
    strides.append((strides[-1][-1], size));
    return [([x[low:high] for x in arrays] + extra_args) for (low, high) in strides];
}

"""Remove AWS @-based region specification from file.

    Tools such as Toil use us-east-1 bucket lookup, then pick region
    from boto.
    """
def clean_file(f: str, config: dict[str, str]) -> str {
    (approach, rest) = f.split("://");
    (bucket_region, key) = rest.split("/", 1);
    if bucket_region.find("@") > 0 {
        (bucket, region) = bucket_region.split("@");
    } else {
        bucket = bucket_region;
    }
    if config.get("input_type") in ["http", "https"] {
        return "https://s3.amazonaws.com/%s/%s" % (bucket, key);
    }
    return "%s://%s/%s" % (approach, bucket, key);
}

