glob BYTE_MASK = 0xFF;

"""
    Extract bit(s) value from a byte.

    BYTE INDEX =  | 0 | 1 | 2 | 3 || 4 | 5 | 6 | 7 |
                 msb                              lsb
                 128                               1
"""
def byte_bit_value(byte: int, schema: list[int] | tuple[int, int]) -> int {
    (index, bits) = schema;
    if index < 0 or index > 7 {
        raise ValueError("Schema index must be 0 thru 7");
    }
    if bits < 1 or bits > 8 {
        raise ValueError("Schema bits must be 1 thru 8");
    }
    if len(list(bin(byte)[2:])) > 8 {
        raise ValueError("Number too big. Not a byte value.");
    }
    if index == 0 and bits == 8 {
        return byte;
    }
    shift = 8 - (index + bits);
    mask = BYTE_MASK >> (shift + index);
    return (byte >> shift) & mask;
}

"""Move operation.

    move position X to position Y means that the letter which is at
    index X should be removed from the string, then inserted such that it
    ends up at index Y.

    """
def move(text: str, i: int, j: int) -> str {
    chars = [t for t in text];
    letter = chars[i];
    chars.pop(i);
    chars.insert(j, letter);
    return "".join(chars);
}

