glob MAX_CUTOUT_NPIX = 256;

"""Construct the UNWISE specific URL to download UNWISE cutouts."""
def get_unwise_image_url(
    ra: float, dec: float, npix: float, band: str, data_release: str, filetype: str = "image"
) -> str | None {
    if npix >= MAX_CUTOUT_NPIX {
        npix = MAX_CUTOUT_NPIX;
    }
    datatype = {
        "image": "&file_img_m=on",
        "std": "&file_std_m=on",
        "invvar": "&file_invvar_m=on"
    };
    file_type = datatype[filetype];
    base = "http://unwise.me/cutout_fits?version={}&".format(data_release);
    ra_part = "ra={:0}&".format(ra);
    dec_part = "dec={:0}&".format(dec);
    size = "size={:0}&".format(npix);
    if data_release in ('neo4', 'neo5', 'neo6') and band in ('3', '4') {
        print(
            '[ERROR] Download of band w{} in unwise-{} not available'.format(
                band, data_release
            )
        );
        return None;
    }
    band_part = "bands={0:s}".format(band);
    return base + ra_part + dec_part + size + band_part + file_type;
}

