"""Get frequency weighted intersection over union."""
def get_frequency_weighted_iou(n: dict[int, dict[int, int]]) -> float {
    k = len(n[0]);
    t = [sum([n[i][j] for j in range(k)]) for i in range(k)];
    a = sum(t) ** -1;
    b = sum(
        [
            (t[i] * n[i][i]) / ((t[i] - n[i][i]) + sum([n[j][i] for j in range(k)]))
            for i in range(k)
        ]
    );
    return a * b;
}

"""Like ord(), but takes multiple characters. I.e. calculate the base10 equivalent of a string considered as a set of base-256 digits."""
def multiord(x: str) -> int {
    num = 0;
    scale = 1;
    for i in range(len(x) - 1, -1, -1) {
        num = num + ord(x[i]) * scale;
        scale = scale * 256;
    }
    return num;
}

