glob OCTET_HIGH_NIBBLE_MASK = 0xF0;
glob CGNAT_OCTET_MASK = 0xC0;
glob CGNAT_OCTET_VALUE = 64;
glob PRIVATE_172_OCTET_VALUE = 16;
glob BENCHMARK_OCTET_MASK = 0xFE;
glob BENCHMARK_OCTET_VALUE = 18;
glob MULTICAST_CLASS = 0xE0;

"""IPv4 address filter: reject short strings and bogon/reserved ranges."""
def ipv4_filter(value: str, index: int = 0, pattern: str | None = None) -> bool {
    ip = value;
    if len(ip) < 8 {
        return False;
    }
    octets = ip.split('.');
    byte1 = int(octets[0]);
    byte2 = int(octets[1]);
    if ip.startswith(('0.', '10.', '127.', '169.254.', '192.0.0.', '192.0.2.', '192.168.', '198.51.100.', '203.0.113.')) {
        return False;
    }
    if ip.startswith('100.') and byte2 & CGNAT_OCTET_MASK == CGNAT_OCTET_VALUE {
        return False;
    }
    if ip.startswith('172.') and byte2 & OCTET_HIGH_NIBBLE_MASK == PRIVATE_172_OCTET_VALUE {
        return False;
    }
    if ip.startswith('198.') and byte2 & BENCHMARK_OCTET_MASK == BENCHMARK_OCTET_VALUE {
        return False;
    }
    if byte1 & OCTET_HIGH_NIBBLE_MASK == MULTICAST_CLASS {
        return False;
    }
    if byte1 & OCTET_HIGH_NIBBLE_MASK == OCTET_HIGH_NIBBLE_MASK {
        return False;
    }
    if ip.endswith('.0') or ip.endswith('.255') {
        return False;
    }
    return True;
}

"""Calculates the Levenshtein distance between *strings* a and b.

from http://hetland.org/coding/python/levenshtein.py

"""
def levenshtein(a: str, b: str) -> int {
    (n, m) = (len(a), len(b));
    if n > m {
        (a, b) = (b, a);
        (n, m) = (m, n);
    }
    current = range(n + 1);
    for i in range(1, m + 1) {
        (previous, current) = (current, [i] + [0] * n);
        for j in range(1, n + 1) {
            (add, delete) = (previous[j] + 1, current[j - 1] + 1);
            change = previous[j - 1];
            if a[j - 1] != b[i - 1] {
                change = change + 1;
            }
            current[j] = min(add, delete, change);
        }
    }
    return current[n];
}

