glob LEB128_CONTINUATION = 0x80;
glob LEB128_PAYLOAD_MASK = 0x7F;

"""Read variable length encoded 128 bits unsigned integer

    .. doctest::

        >>> from ppci.utils.leb128 import unsigned_leb128_decode
        >>> signed_leb128_decode(iter(bytes([0xe5, 0x8e, 0x26])))
        624485
    """
def unsigned_leb128_decode(data: Iterator[int]) -> int {
    result = 0;
    shift = 0;
    while True {
        byte = next(data);
        result |= (byte & LEB128_PAYLOAD_MASK) << shift;
        if byte & LEB128_CONTINUATION == 0 {
            break;
        }
        shift += 7;
    }
    result
}

