glob WORD_SEPARATORS = " \t\n&|";

"""Exract word (space separated) at current index."""
def extractWordInString(strToParse: str, index: int) -> str {
    i = index;
    while i != 0 and strToParse[i - 1] not in WORD_SEPARATORS {
        i = i - 1;
    }
    left_part = strToParse[i:index];
    i = index;
    while i != len(strToParse) and strToParse[i] not in WORD_SEPARATORS {
        i = i + 1;
    }
    right_part = strToParse[index:i];
    return left_part + right_part;
}

