"""Remove consecutive duplicate tokens so only changes remain.

e.g. ABC ABC ABC EE A S X X SD becomes ABC EE A S X SD.
"""
def lossy_compresion(text: str, token_separator: str = " ") -> str {
    compressed: list[str] = [];
    tokenized = text.split(token_separator);
    previous: str | None = None;
    for token in tokenized {
        if token != previous {
            compressed.append(token);
            previous = token;
        }
    }
    return " ".join(compressed);
}

