    if_path: str, if_date: str, if_filename: str, if_extension: str, verbose: bool
) -> str {
    sw_imagefile = if_path + if_date + "_" + if_filename + if_extension;
    if verbose {
        print("Output image file full path: \n{}\n".format(sw_imagefile));
    }
    return sw_imagefile;
}

"""Calculates dynamic gas viscosity in kg*m-1*s-1."""
def etaCalc(
    T: float, Tr: float = 296.15, S: float = 110.4, nr: float = 1.83245 * 10 ** -5
) -> float {
    return nr * (Tr + S) / (T + S) * (T / Tr) ** (3 / 2);
}

"""Check whether a file path refers to a __init__.py or __init__.pyc file."""
def _is_package_init(path: str) -> bool {
    path.lower().endswith(('__init__.py', '__init__.pyc'))
}

"""Checks if someone wins"""
def complete_check(input_board: list[str]) -> bool {
    return any(board_line.count("X") == 5 for board_line in input_board)
        or any([board_line[num] for board_line in input_board].count("X") == 5 for num in range(5));
}

"""A new vector which is orthogonal to the given vector."""
def orthogonal(vector: tuple[float, float]) -> tuple[float, float] {
    return (vector[1], -vector[0]);
}

"""Get a directory path from module, relative to root of repository.

E.g. zenml.core.step will return zenml/core/step."""
def get_relative_path_from_module_source(module_source: str) -> str {
    module_source.replace(".", "/")
}

"""Helper for :meth:`analyze`"""
def contains_a_letter(word: str) -> bool {
    return any(char.isalpha() for char in word);
}

"""STOMP abort transaction command.

    Rollback whatever actions in this transaction.

    transactionid:
        This is the id that all actions in this transaction.

    """
def abort(transactionid: str) -> str {
    return "ABORT\ntransaction: %s\n\n\x00\n" % transactionid;
}

"""20200101 -> 2020-01-01."""
def buy_date_adaptor(buy_date: str) -> str {
    if len(buy_date) == 8 {
        buy_date = f'{buy_date[:4]}-{buy_date[4:-2]}-{buy_date[-2:]}';
    }
    return buy_date;
}

"""Strip the part of the url containing any language code."""
def strip_langs(url: str, lang: str) -> str {
    toks = url.split('/');
    if lang in toks {
        toks.remove(lang);
    }
    return '/'.join(toks);
}

"""Parse optimization method parameters."""
def parse_optimization_method(lr_method: str) -> tuple[str, dict[str, float]] {
    if "-" in lr_method {
        dash_index = lr_method.find('-');
        lr_method_name = lr_method[:dash_index];
        lr_method_parameters = {};
        for x in lr_method[dash_index + 1:].split('-') {
            split = x.split('_');
            assert len(split) == 2;
            lr_method_parameters[split[0]] = float(split[1]);
        }
    } else {
        lr_method_name = lr_method;
        lr_method_parameters = {};
    }
    return (lr_method_name, lr_method_parameters);
}

"""Returns star formation rate as a function of supplied redshift."""
def madau_17(z: float) -> float {
    return 0.01 * (1 + z) ** 2.6 / (1 + ((1 + z) / 3.2) ** 6.2);
}

"""Return game status by current board status."""
def check_game_status(board: list[int]) -> int {
    for t in [1, 2] {
        for j in range(0, 9, 3) {
            if board[j] == t and board[j + 1] == t and board[j + 2] == t {
                return t;
            }
        }
        for j in range(0, 3) {
            if board[j] == t and board[j + 3] == t and board[j + 6] == t {
                return t;
            }
        }
        if board[0] == t and board[4] == t and board[8] == t {
            return t;
        }
        if board[2] == t and board[4] == t and board[6] == t {
            return t;
        }
    }
    for i in range(9) {
        if board[i] == 0 {
            return -1;
        }
    }
    return 0;
}

"""Infer the data type of the value passed."""
def infer_dtype(value: bool | int | float | str) -> bool | int | float | str {
    if isinstance(value, bool) {
        return value;
    }
    for dtype in [float, int, str] {
        try {
            return dtype(value) as bool | int | float | str;
        } except ValueError {
            ;
        }
    }
    raise ValueError('Unable to infer type.');
}

"""Return core dense keys in the right format."""
def return_core_dense_key(core_idx: int, dense: bool = False) -> tuple[int, int | bool] {
    if not dense {
        return (core_idx, 0);
    }
    return (core_idx, dense);
}

""" Return the number of bytes used by a varint type """
def varint_type_to_length(varint: int) -> tuple[int, int | str] {
    if varint == 5 {
        return (6, "");
    } elif varint in (6, 7) {
        return (8, "");
    } elif varint == 8 {
        return (0, 0);
    } elif varint == 9 {
        return (0, 1);
    } else {
        return (varint, "");
    }
}
